#!/usr/bin/env python3
"""Autorenwerkzeug: Johannesevangelium Kapitel 1–7 (einschliesslich [[JHN.7.53]]) – Befunde, Deutungen, Grundsätze,
Anwendungen, offene Fragen, Beziehungen, Hintergrund zu Abschnitten, Kapitel-Zusammenfassungen und Studie; jeweils mit
Züridüütsch-Lokalisierung.

Abgrenzung: Hintergrund zum ganzen Buch steht in BG-JHN-BOOK-0001 (Lieblingsjünger, Gemeinde, Datierung, 𝔓52) und
BG-JHN-BOOK-0002 (Verhältnis zu den anderen Evangelien, drei Passafeste, Todestag) und wird hier nicht wiederholt.
Nummernbereich dieses Werkzeugs: 1001–1999. Die Kontexte CTX-JHN-READERS-0095 und CTX-GALILEE-0030 werden nur
verwendet, nie geschrieben: run() liest CTX-JHN-READERS-0095 aus der Datei und gibt ihn unverändert weiter, sodass
_lib.write nichts ändert.

Abschnitte: Jede Aussage nennt den Versbereich, auf den sie sich bezieht; zugeordnet wird die kleinste vorhandene
Texteinheit (data/text-units/TU-JHN-…), die ihn ganz enthält, sonst die Kapiteleinheit.
Zählungen: nach den MACULA-Lemmata zum SBLGNT (data/annotations/MACULA-SBLGNT-JHN-0nn.json), einschliesslich des
Abschnitts in Doppelklammern ([[JHN.7.53-JHN.8.11]]), soweit er in den gezählten Bereich fällt.
Handschriftenangaben: aus den CNTR-Transkriptionen (data/witness-texts/CNTR-…-JHN.json), maschinell gelesen, nicht am
Faksimile geprüft. Die Übersetzungen TRANS-JHN-00n-… werden zitiert, wie sie am 2026-10-14 vorlagen.

Aufruf: python3 scripts/authoring/johannes_study_a.py
KI-Entwurf (Claude) vom 2026-10-14 auf Wunsch von Andi Neck; keine fachliche Prüfung erfolgt.
"""
import json
import re
import sys
import pathlib

sys.path.insert(0, str(pathlib.Path(__file__).resolve().parent))
from _lib import D  # noqa: E402

TAGS = ["TAG-JOHN"]
CHAPTERS = {1: "TU-JHN-001-001-051", 2: "TU-JHN-002-001-025", 3: "TU-JHN-003-001-036", 4: "TU-JHN-004-001-054",
            5: "TU-JHN-005-001-047", 6: "TU-JHN-006-001-071", 7: "TU-JHN-007-001-053"}
_UNITS = sorted(p.stem for p in (D / "text-units").rglob("TU-JHN-*.json"))
CTX_READERS = "CTX-JHN-READERS-0095"
CTX_JESUS = "CTX-GALILEE-0030"


def U(ch, v1, v2=None):
    """Kleinste vorhandene Texteinheit, die Kapitel ch, Verse v1–v2 ganz enthält; sonst die Kapiteleinheit."""
    v2 = v2 or v1
    best = None
    for uid in _UNITS:
        m = re.fullmatch(r"TU-JHN-(\d{3})-(\d{3})-(\d{3})", uid)
        if m and int(m[1]) == ch and int(m[2]) <= v1 and int(m[3]) >= v2:
            if best is None or int(m[3]) - int(m[2]) < best[0]:
                best = (int(m[3]) - int(m[2]), uid)
    return best[1] if best else CHAPTERS[ch]


MAC = "Zählung nach den MACULA-Lemmata zum SBLGNT."
MAC_G = "Zellig nach de MACULA-Lemmata zum SBLGNT."
CNTR = ("Handschriftenangaben aus den CNTR-Transkriptionen, maschinell ausgewertet und nicht am Faksimile geprüft; "
        "Schreibweisen der Handschriften (Itazismen, Abkürzungen der heiligen Namen wie =θσ für θεός) sind nicht normalisiert.")
CNTR_G = ("Handschrifte-Aagaabe us de CNTR-Transkriptione, maschinell uusgwärtet und nöd am Faksimile prüeft; "
          "d Schriibwiise vo de Handschrifte (Itazisme, Abchürzige vo de heilige Name wie =θσ für θεός) sind nöd normalisiert.")

