# (id, Abschnitt, Stelle, Kontext, Konfidenz, Thema, Text, Unsicherheit, Belege, Quellen, Fachwörter |
#  Mundart: Thema, Text, Unsicherheit, Fachwörter)
BACKGROUND = [
 ("BG-JHN-1001", U(1, 19, 28), "JHN.1.28", CTX_JESUS, "possible", "Betanien jenseits des Jordan",
  "Der Ort, an dem Johannes tauft, ist nicht das Betanien bei Jerusalem, wo Lazarus wohnt ([[JHN.11.1]]; [[JHN.11.18]]), sondern ein Betanien «jenseits des Jordan», also östlich des Flusses ([[JHN.1.28]]); Jesus kehrt später dorthin zurück ([[JHN.10.40]]). Origenes schrieb im 3. Jahrhundert, er habe dort kein Betanien gefunden, wohl aber einen Ort Betabara, den man als Taufstelle zeige; so lesen auch einige Handschriften, nach der CNTR-Transkription etwa 029 (βηθαβαρα). Die Mosaikkarte von Madaba (6. Jahrhundert) zeigt Betabara als Taufort des Johannes. Heute wird die Stelle im Wadi al-Charrar auf der jordanischen Seite gezeigt.",
  "Die Lage ist nicht gesichert. Manche denken nicht an einen Ort am unteren Jordan, sondern an die Landschaft Batanäa (Baschan) im Nordosten; dann wäre «Betanien» eine Gegend, nicht ein Dorf.",
  ["JHN.1.28", "JHN.10.40", "JHN.11.1", "JHN.11.18"], ["Origenes, Kommentar zum Johannesevangelium 6,40", "Mosaikkarte von Madaba"],
  [("grc", "πέραν τοῦ Ἰορδάνου", "jenseits des Jordan")],
  "Betanie ännet em Jordan",
  "De Ort, wo de Johannes tauft, isch nöd s Betanie bi Jerusalem, wo de Lazarus wohnt ([[JHN.11.1]]; [[JHN.11.18]]), sondern es Betanie «ännet em Jordan», also östlich vom Fluss ([[JHN.1.28]]); de Jesus chunnt spööter dethi zrugg ([[JHN.10.40]]). De Origenes hät im 3. Jaarhundert gschribe, er heb dört kei Betanie gfunde, aber en Ort Betabara, wo me als Toufstell zeigi; eso läsed au es paar Handschrifte, nach de CNTR-Transkription öppe 029 (βηθαβαρα). D Mosaikcharte vo Madaba (6. Jaarhundert) zeigt Betabara als Toufort vom Johannes. Hüt wird d Stell im Wadi al-Charrar uf de jordanische Siite zeigt.",
  "Wo s gläge isch, isch nöd gsicheret. Mängi dänked nöd a en Ort am undere Jordan, sondern a d Landschaft Batanäa (Baschan) im Nordoschte; dänn wär «Betanie» e Gäged, nöd es Dorf.",
  ["ännet em Jordan"]),
 ("BG-JHN-1002", U(1, 35, 42), "JHN.1.39", CTX_JESUS, "probable", "Die Stunden des Tages",
  "Man teilte den hellen Tag von Sonnenaufgang bis Sonnenuntergang in zwölf Stunden ([[JHN.11.9]]); ihre Länge schwankte mit der Jahreszeit. Die zehnte Stunde ([[JHN.1.39]]) ist danach der späte Nachmittag, etwa um 16 Uhr; die sechste Stunde ([[JHN.4.6]]) die Mittagszeit, die siebte ([[JHN.4.52]]) der frühe Nachmittag. Wer zur zehnten Stunde bei Jesus einkehrt und «jenen Tag» bleibt, bleibt bis zum Abend oder über Nacht.",
  "Einige Ausleger (z. B. B. F. Westcott) nahmen an, Johannes zähle die Stunden wie die römische Rechtsordnung ab Mitternacht; dann wäre die zehnte Stunde 10 Uhr vormittags. Die meisten halten das für unwahrscheinlich. Die Frage spielt auch für [[JHN.19.14]] (sechste Stunde) gegenüber [[MRK.15.25]] (dritte Stunde) eine Rolle.",
  ["JHN.1.39", "JHN.4.6", "JHN.4.52", "JHN.11.9", "JHN.19.14", "MRK.15.25"], [],
  [("grc", "ὥρα", "Stunde; Zeitpunkt")],
  "D Stunde vom Tag",
  "Me hät de hell Tag vom Sunneufgang bis zum Sunneundergang i zwölf Stund iiteilt ([[JHN.11.9]]); wie lang si gsii sind, hät mit de Jaresziit gwächslet. Di zäät Stund ([[JHN.1.39]]) isch dänn de spaat Namittag, öppe um vieri; di sächst Stund ([[JHN.4.6]]) d Mittagsziit, di sibet ([[JHN.4.52]]) de früe Namittag. Wer zur zääte Stund bim Jesus iichehrt und «dä Tag» bliibt, bliibt bis am Aabig oder über Nacht.",
  "Es paar Uusleger (z. B. de B. F. Westcott) händ aagnoo, de Johannes zelli d Stunde wie s römisch Rächt ab Mitternacht; dänn wär di zäät Stund am zäni am Morge. Di meischte halted das für unwahrschiinli. D Frag spilt au für [[JHN.19.14]] (sächsti Stund) gägenüber [[MRK.15.25]] (dritti Stund) e Rolle.",
  ["Stund; Zitpunkt"]),
 ("BG-JHN-1003", U(2, 1, 12), "JHN.2.6", CTX_JESUS, "probable", "Steinerne Krüge für die Reinigung",
  "Gefässe aus Stein galten nach jüdischer Reinheitsauffassung als unempfänglich für Unreinheit; die Mischna setzt das voraus (Kelim 10,1; Para 3,2). Darum eigneten sie sich für Wasser, mit dem man sich vor dem Essen die Hände wusch oder Geräte reinigte (vgl. [[MRK.7.3-MRK.7.4]]). Archäologisch sind Steingefässe in Jerusalem und Galiläa für die Zeit vom 1. Jahrhundert v. Chr. bis ins 2. Jahrhundert n. Chr. sehr häufig belegt, auch grosse, auf der Drehbank gearbeitete Krüge; Werkstätten sind bei Jerusalem und bei Reina nahe Nazaret nachgewiesen. Ein Metretes (μετρητής) fasste rund 39 Liter; sechs Krüge zu zwei oder drei Metreten ergeben zusammen etwa 480 bis 700 Liter ([[JHN.2.6]]).",
  "Die Mischna wurde um 200 n. Chr. abgeschlossen; wie weit ihre Regeln das Galiläa der Zeit Jesu beschreiben, ist im Einzelnen offen. Die Literangabe für den Metretes ist ein Näherungswert; Masse schwankten regional.",
  ["JHN.2.6", "MRK.7.3-MRK.7.4"], ["Mischna, Kelim 10,1; Para 3,2"],
  [("grc", "ὑδρία", "Wasserkrug"), ("grc", "μετρητής", "Metretes, Hohlmass von etwa 39 Litern"), ("grc", "καθαρισμός", "Reinigung")],
  "Steinigi Chrüeg für d Reinigung",
  "Gfäss us Stei händ nach de jüdische Uffassig vo Reinheit nöd chöne unrein wärde; d Mischna setzt das voruus (Kelim 10,1; Para 3,2). Drum händ si sich für Wasser eignet, mit däm me sich vor em Ässe d Händ gwäsche oder Grät gsüüberet hät (vgl. [[MRK.7.3-MRK.7.4]]). Archäologisch sind Steigfäss z Jerusalem und z Galiläa für d Ziit vom 1. Jaarhundert v. Chr. bis is 2. Jaarhundert n. Chr. sehr hüüfig beleit, au grossi Chrüeg, wo uf de Dreibank gmacht worde sind; Wärchstätte sind bi Jerusalem und bi Reina nööch bi Nazaret nachgwise. En Metretes (μετρητής) hät öppe 39 Liter gfasst; sächs Chrüeg mit zwei oder drüü Metrete gänd zäme öppe 480 bis 700 Liter ([[JHN.2.6]]).",
  "D Mischna isch um 200 n. Chr. abgschlosse worde; wie wiit iri Regle s Galiläa vo de Ziit vom Jesus beschriibed, isch im Einzelne offe. D Literaagaab für de Metretes isch en Nööcherigswärt; d Määs händ regional gschwankt.",
  ["Wasserchrueg", "Metretes, Hohlmass vo öppe 39 Liter", "Reinigung"]),
 ("BG-JHN-1004", U(2, 13, 22), "JHN.2.20", CTX_JESUS, "probable", "Der Tempel des Herodes und die sechsundvierzig Jahre",
  "Herodes der Grosse begann nach Josephus im 18. Jahr seiner Herrschaft, also 20/19 v. Chr., den Tempel in Jerusalem neu zu bauen (Jüdische Altertümer 15,380); das Tempelhaus selbst war nach anderthalb Jahren fertig (15,421), am ganzen Bezirk wurde bis in die 60er-Jahre n. Chr. gearbeitet (20,219). Sechsundvierzig Jahre nach Baubeginn ([[JHN.2.20]]) führen etwa in die Jahre 27/28 n. Chr. Im äusseren Vorhof wurden Opfertiere verkauft und Münzen getauscht; die Tempelsteuer war in tyrischen Silbermünzen zu entrichten, und nach der Mischna standen die Tische der Wechsler vor dem Passa auch im Tempel (Schekalim 1,3). Johannes unterscheidet den ganzen Tempelbezirk (ἱερόν, [[JHN.2.14-JHN.2.15]]) vom Tempelhaus (ναός, [[JHN.2.19-JHN.2.21]]).",
  "Ob [[JHN.2.20]] meint «46 Jahre lang ist gebaut worden» oder «seit 46 Jahren steht das Tempelhaus», ist sprachlich umstritten; die Jahresrechnung hängt zudem davon ab, wie man die Herrschaftsjahre des Herodes zählt.",
  ["JHN.2.13-JHN.2.22"], ["Josephus, Jüdische Altertümer 15,380; 15,421; 20,219", "Mischna, Schekalim 1,3"],
  [("grc", "ἱερόν", "Tempelbezirk, Heiligtum"), ("grc", "ναός", "Tempelhaus, Heiligtum im engeren Sinn"), ("grc", "κολλυβιστής", "Geldwechsler")],
  "De Tämpel vom Herodes und di sächsevierzg Jaar",
  "De Herodes de Gross hät nach em Josephus im 18. Jaar vo sinere Herrschaft, also 20/19 v. Chr., aagfange, de Tämpel z Jerusalem nöi z boue (Jüdischi Altertümer 15,380); s Tämpelhuus sälber isch nach anderthalb Jaar fertig gsii (15,421), am ganze Beziirk hät me bis i d 60er-Jaar n. Chr. gschaffet (20,219). Sächsevierzg Jaar nach em Buubeginn ([[JHN.2.20]]) füered öppe i d Jaar 27/28 n. Chr. Im üssere Vorhof hät me Opfertier verchauft und Münze gwächslet; d Tämpelstüür hät me i tyrische Silbermünze müese zale, und nach de Mischna sind d Tisch vo de Wächsler vor em Passa au im Tämpel gstande (Schekalim 1,3). De Johannes underscheidet de ganz Tämpelbeziirk (ἱερόν, [[JHN.2.14-JHN.2.15]]) vom Tämpelhuus (ναός, [[JHN.2.19-JHN.2.21]]).",
  "Öb [[JHN.2.20]] meint «46 Jaar lang isch buut worde» oder «sit 46 Jaar staat s Tämpelhuus», isch spraachlich umstritte; d Jaresrächnig hanget usserdem devo ab, wie me d Herrschaftsjaar vom Herodes zellt.",
  ["Tämpelbeziirk, Heiligtum", "Tämpelhuus, Heiligtum im ängere Sinn", "Gältwächsler"]),
 ("BG-JHN-1005", U(4, 1, 15), "JHN.4.9", CTX_JESUS, "probable", "Samaritaner und der Berg Garizim",
  "Die Samaritaner lebten im Bergland zwischen Judäa und Galiläa, um Sichem und den Berg Garizim. Sie anerkannten nur die fünf Bücher Mose als heilige Schrift und verehrten Gott auf dem Garizim, auf dem nach [[DEU.11.29]] und [[DEU.27.12]] der Segen gesprochen werden sollte; ihr Tempel dort wurde von Johannes Hyrkanus Ende des 2. Jahrhunderts v. Chr. zerstört (Josephus, Jüdische Altertümer 13,254–256). Das Verhältnis zu den Juden war gespannt; Josephus berichtet von Zwischenfällen, etwa von Samaritanern, die Gebeine im Tempel verstreuten (18,29–30), und von einem Überfall auf galiläische Festpilger (20,118). Später ist bei den Samaritanern die Erwartung eines «Taheb» bezeugt, eines wiederkehrenden Propheten wie Mose nach [[DEU.18.15-DEU.18.18]]. Der Satz «Juden verkehren nicht mit Samaritern» ([[JHN.4.9]]) kann auch heissen: «Juden benutzen keine Gefässe gemeinsam mit Samaritern» (David Daube 1950); die Mischna hält samaritanische Frauen grundsätzlich für unrein (Nidda 4,1).",
  "Die Zeugnisse über den Taheb stammen erst aus dem 4. Jahrhundert und später; ob die Frau in [[JHN.4.25]] eine solche Erwartung meint, ist offen. Die Mischna-Regel ist jünger als das Evangelium.",
  ["JHN.4.4-JHN.4.26", "DEU.11.29", "DEU.27.12", "DEU.18.15-DEU.18.18"],
  ["Josephus, Jüdische Altertümer 13,254–256; 18,29–30; 20,118", "David Daube, Jesus and the Samaritan Woman: The Meaning of συγχράομαι, Journal of Biblical Literature 69 (1950), 137–147", "Mischna, Nidda 4,1"],
  [("grc", "συγχράομαι", "gemeinsam gebrauchen; Umgang haben"), ("grc", "Σαμαρίτης", "Samariter, Samaritaner")],
  "D Samaritaner und de Bärg Garizim",
  "D Samaritaner händ im Bärgland zwüsched Judäa und Galiläa gläbt, um Sichem und de Bärg Garizim. Si händ nu di föif Büecher Mose als heiligi Schrift aagnoo und Gott uf em Garizim verehrt, wo nach [[DEU.11.29]] und [[DEU.27.12]] de Säge söll gsproche wärde; iren Tämpel dört isch vom Johannes Hyrkanus am Änd vom 2. Jaarhundert v. Chr. zerstört worde (Josephus, Jüdischi Altertümer 13,254–256). S Verhältnis zu de Jude isch gspannt gsii; de Josephus bricht vo Zwüschefäll, öppe vo Samaritaner, wo Chnoche im Tämpel verströit händ (18,29–30), und vo me Überfall uf galiläischi Fäschtpilger (20,118). Spööter isch bi de Samaritaner d Erwartig vo me «Taheb» bezüügt, vo me Prophet wie de Mose, wo wider chunnt, nach [[DEU.18.15-DEU.18.18]]. De Satz «D Jude händ nüüt mit de Samaritaner z tue» ([[JHN.4.9]]) cha au heisse: «D Jude bruuched kei Gfäss gmeinsam mit de Samaritaner» (David Daube 1950); d Mischna haltet samaritanischi Fraue grundsätzlich für unrein (Nidda 4,1).",
  "D Züügnis über de Taheb stammed erscht us em 4. Jaarhundert und spööter; öb d Frau i [[JHN.4.25]] e settigi Erwartig meint, isch offe. D Regle vo de Mischna isch jünger als s Evangelium.",
  ["gmeinsam bruuche; mitenand z tue ha", "Samariter, Samaritaner"]),
 ("BG-JHN-1006", U(4, 1, 15), "JHN.4.5", CTX_JESUS, "probable", "Sychar und die Jakobsquelle",
  "Sychar lag nahe dem Feld, das Jakob seinem Sohn Josef gab ([[JHN.4.5]]; vgl. [[GEN.33.18-GEN.33.20]]; [[GEN.48.22]]; [[JOS.24.32]]); man sucht es meist beim heutigen Askar oder setzt es mit dem alten Sichem gleich. Dass Jakob dort einen Brunnen gab, sagt das Alte Testament nicht; es ist eine Überlieferung, die die Frau voraussetzt ([[JHN.4.12]]). Der heute gezeigte Brunnen liegt bei Tell Balata am Rand von Nablus in einer Kirche und ist sehr tief. Johannes nennt ihn abwechselnd «Quelle» (πηγή, [[JHN.4.6]]) und «Brunnen» (φρέαρ, [[JHN.4.11-JHN.4.12]]); ein Brunnen, der von Grundwasser gespeist wird, kann beides sein. Wer am Brunnen Wasser holen wollte, brauchte ein eigenes Schöpfgefäss ([[JHN.4.11]]).",
  "Die Gleichsetzung des heutigen Brunnens mit dem in [[JHN.4.6]] beruht auf alter Pilgerüberlieferung (seit dem 4. Jahrhundert), nicht auf einer Inschrift. Welcher Ort Sychar war, ist umstritten.",
  ["JHN.4.5-JHN.4.15", "GEN.33.18-GEN.33.20", "GEN.48.22", "JOS.24.32"], [],
  [("grc", "πηγή", "Quelle"), ("grc", "φρέαρ", "Brunnen, Schacht"), ("grc", "ἄντλημα", "Schöpfgefäss")],
  "Sychar und d Jakobsquälle",
  "Sychar isch nööch bi dem Fäld gläge, wo de Jakob sim Sohn Josef ggää hät ([[JHN.4.5]]; vgl. [[GEN.33.18-GEN.33.20]]; [[GEN.48.22]]; [[JOS.24.32]]); me suecht s meischt bim hütige Askar oder setzt s mit em alte Sichem gliich. Dass de Jakob dört en Brunne ggää hät, seit s Alt Teschtament nöd; es isch e Überliferig, wo d Frau voruussetzt ([[JHN.4.12]]). De Brunne, wo me hüt zeigt, liit bi Tell Balata am Rand vo Nablus imene Chile und isch sehr tüüf. De Johannes nännt en abwächsligswiis «Quälle» (πηγή, [[JHN.4.6]]) und «Brunne» (φρέαρ, [[JHN.4.11-JHN.4.12]]); en Brunne, wo vom Grundwasser gspise wird, cha beides sii. Wer am Brunne hät wele Wasser hole, hät es eigets Schöpfgfäss bruucht ([[JHN.4.11]]).",
  "Dass de hütig Brunne dä i [[JHN.4.6]] isch, beruet uf alter Pilger-Überliferig (sit em 4. Jaarhundert), nöd uf ere Inschrift. Wele Ort Sychar gsii isch, isch umstritte.",
  ["Quälle", "Brunne, Schacht", "Schöpfgfäss"]),
 ("BG-JHN-1007", U(4, 43, 54), "JHN.4.46", CTX_JESUS, "probable", "Ein königlicher Beamter zwischen Kana und Kafarnaum",
  "Ein «königlicher» (βασιλικός) war ein Beamter oder Offizier im Dienst eines Herrschers, hier am ehesten des Herodes Antipas, der von 4 v. Chr. bis 39 n. Chr. als Tetrarch über Galiläa und Peräa herrschte und im Volk auch «König» genannt wurde (vgl. [[MRK.6.14]]). Kafarnaum lag am Nordufer des Sees, rund 210 Meter unter dem Meeresspiegel; Kana im Bergland Galiläas, je nach Lokalisierung 25 bis 30 Kilometer entfernt. Daher «komm hinab» ([[JHN.4.47]]; [[JHN.4.49]]) und der Rückweg, der bis zum folgenden Tag dauert ([[JHN.4.52]]).",
  "Wo Kana lag, ist umstritten: Vorgeschlagen werden vor allem Chirbet Qana am Nordrand der Ebene Bet Netofa und Kafr Kanna nahe Nazaret, wo die Pilgerüberlieferung den Ort zeigt. Ob der Beamte Jude oder Nichtjude war, sagt der Text nicht.",
  ["JHN.2.1", "JHN.4.46-JHN.4.54", "MRK.6.14"], [],
  [("grc", "βασιλικός", "königlich; königlicher Beamter")],
  "En königliche Beamte zwüsched Kana und Kafarnaum",
  "En «königliche» (βασιλικός) isch en Beamte oder en Offizier im Dienscht vo me Herrscher gsii, da am eheschte vom Herodes Antipas, wo vo 4 v. Chr. bis 39 n. Chr. als Tetrarch über Galiläa und Peräa gherrscht hät und im Volk au «König» gnännt worde isch (vgl. [[MRK.6.14]]). Kafarnaum isch am Nordufer vom See gläge, rund 210 Meter under em Meeresspiegel; Kana im Bärgland vo Galiläa, je nach Lokalisierig 25 bis 30 Kilometer wiit wäg. Drum «chumm abe» ([[JHN.4.47]]; [[JHN.4.49]]) und de Heiwäg, wo bis am nächschte Tag gaat ([[JHN.4.52]]).",
  "Wo Kana gläge isch, isch umstritte: Vorgschlage wärded vor allem Chirbet Qana am Nordrand vo de Äbni Bet Netofa und Kafr Kanna nööch bi Nazaret, wo d Pilger-Überliferig de Ort zeigt. Öb de Beamt en Jud oder kein Jud gsii isch, seit de Text nöd.",
  ["königlich; königliche Beamte"]),
 ("BG-JHN-1008", U(5, 1, 9), "JHN.5.2", CTX_JESUS, "probable", "Der Teich beim Schaftor",
  "Das Schaftor lag im Norden der Tempelanlage (vgl. [[NEH.3.1]]; [[NEH.12.39]]). Bei der heutigen St.-Anna-Kirche in Jerusalem wurden zwei grosse, durch einen Damm getrennte Becken freigelegt; vier Säulenhallen um die Becken und eine auf dem Damm würden die «fünf Säulenhallen» erklären ([[JHN.5.2]]). Östlich davon fanden sich kleinere Becken und Grotten, an denen in römischer Zeit, spätestens im 2. Jahrhundert n. Chr., ein Heilkult (Asklepios bzw. Serapis) bestand. Die Kupferrolle aus Qumran (3Q15) nennt einen Ort «Bet Eschdatajin», was manche als Doppelform des Namens Betesda deuten. «Auf Hebräisch» meint bei Johannes wohl die aramäische Umgangssprache (vgl. [[JHN.19.13]]; [[JHN.19.17]]).",
  "Ob die Becken der Wasserversorgung des Tempels dienten oder als Tauchbad, und ob schon zur Zeit Jesu dort Heilung gesucht wurde, ist umstritten. Zu den Namensformen in den Handschriften siehe FIND-JHN-1016.",
  ["JHN.5.2-JHN.5.7", "NEH.3.1", "NEH.12.39"], ["Kupferrolle aus Qumran (3Q15)"],
  [("grc", "κολυμβήθρα", "Teich, Becken"), ("grc", "στοά", "Säulenhalle"), ("arc", "בֵּית חֶסְדָּא", "Haus der Barmherzigkeit (eine mögliche Deutung von Betesda)", "bēt ḥesdā")],
  "De Teich bim Schaaftor",
  "S Schaaftor isch im Norde vo de Tämpelaalaag gläge (vgl. [[NEH.3.1]]; [[NEH.12.39]]). Bi de hütige St.-Anna-Chile z Jerusalem hät me zwei grossi Becke usgrabe, wo dur en Damm trännt sind; vier Säulehalle um d Becke und eini uf em Damm würded di «föif Säulehalle» erkläre ([[JHN.5.2]]). Östlich devo händ sich chliineri Becke und Grotte gfunde, wo s i römischer Ziit, spöötischtens im 2. Jaarhundert n. Chr., en Heilkult (Asklepios bzw. Serapis) gää hät. D Chupferrolle us Qumran (3Q15) nännt en Ort «Bet Eschdatajin», was mängi als Doppelform vom Name Betesda düüted. «Uf Hebräisch» meint bim Johannes wohl di aramäisch Umgangsspraach (vgl. [[JHN.19.13]]; [[JHN.19.17]]).",
  "Öb d Becke de Wasserversorgig vom Tämpel dient händ oder als Tauchbad, und öb me scho zur Ziit vom Jesus dört Heilig gsuecht hät, isch umstritte. Zu de Namensforme i de Handschrifte lueg FIND-JHN-1016.",
  ["Teich, Becke", "Säulehalle", "Huus vo de Barmherzigkeit (e möglichi Düütig vo Betesda)"]),
 ("BG-JHN-1009", U(5, 10, 18), "JHN.5.10", CTX_JESUS, "probable", "Sabbat: Tragen, Gottes Wirken und Beschneidung",
  "Lasten am Sabbat zu tragen, verbieten schon [[JER.17.21-JER.17.22]] und [[NEH.13.15-NEH.13.19]]; die Mischna nennt als letzte von 39 Hauptarbeiten das Hinaustragen von einem Bereich in einen anderen (Schabbat 7,2). Darum werfen die Juden dem Geheilten das Tragen der Matte vor ([[JHN.5.10]]). Wie Gott am siebten Tag ruht ([[GEN.2.2-GEN.2.3]]) und doch weiter wirkt, beschäftigte jüdische Ausleger: Philon schreibt, Gott höre nie auf zu schaffen (Allegorische Erklärung 1,5–6), spätere rabbinische Texte sagen, Gott gebe am Sabbat weiter Leben und halte Gericht (Bereschit Rabba 11,10). Die Beschneidung am achten Tag ([[LEV.12.3]]) wurde auch an einem Sabbat vollzogen (Mischna, Schabbat 18,3; 19,1–2). Ein späterer Schluss vom Kleineren aufs Grössere, Rabbi Elasar ben Asarja zugeschrieben, lautet: Wenn die Beschneidung eines einzigen Gliedes den Sabbat verdrängt, dann erst recht die Rettung des ganzen Leibes (Babylonischer Talmud, Joma 85b); ähnlich argumentiert Jesus in [[JHN.7.22-JHN.7.23]].",
  "Die rabbinischen Texte sind jünger als das Evangelium; sie zeigen Diskussionen, die älter sein können, belegen aber nicht, wie man zur Zeit Jesu überall urteilte.",
  ["JHN.5.9-JHN.5.18", "JHN.7.21-JHN.7.23", "JER.17.21-JER.17.22", "NEH.13.15-NEH.13.19", "GEN.2.2-GEN.2.3", "LEV.12.3"],
  ["Mischna, Schabbat 7,2; 18,3; 19,1–2", "Philon, Allegorische Erklärung 1,5–6", "Bereschit Rabba 11,10", "Babylonischer Talmud, Joma 85b"],
  [("grc", "σάββατον", "Sabbat"), ("grc", "κράβαττος", "Matte, Tragbett"), ("grc", "περιτομή", "Beschneidung")],
  "Sabbat: Träge, s Würke vo Gott und d Beschniidig",
  "Laschte am Sabbat z träge, verbüüted scho [[JER.17.21-JER.17.22]] und [[NEH.13.15-NEH.13.19]]; d Mischna nännt als letschti vo 39 Hauptarbete s Usetrage vo eim Beriich in en andere (Schabbat 7,2). Drum wärfed d Jude em Gheilte vor, dass er d Matte treit ([[JHN.5.10]]). Wie Gott am sibete Tag rueht ([[GEN.2.2-GEN.2.3]]) und glich wiiter würkt, hät jüdischi Uusleger beschäftiget: De Philon schriibt, Gott hör nie uf z erschaffe (Allegorischi Erklärig 1,5–6), spööteri rabbinischi Text säged, Gott gäb am Sabbat wiiter Läbe und halti Gricht (Bereschit Rabba 11,10). D Beschniidig am achte Tag ([[LEV.12.3]]) hät me au amene Sabbat gmacht (Mischna, Schabbat 18,3; 19,1–2). En spöötere Schluss vom Chliinere uf s Grösser, wo me em Rabbi Elasar ben Asarja zueschriibt, lautet: Wänn d Beschniidig vo me einzige Glid de Sabbat verdrängt, dänn erscht rächt d Rettig vom ganze Liib (Babylonische Talmud, Joma 85b); äänlich argumentiert de Jesus i [[JHN.7.22-JHN.7.23]].",
  "D rabbinische Text sind jünger als s Evangelium; si zeiged Diskussione, wo elter chönd sii, beleged aber nöd, wie me zur Ziit vom Jesus überall gurteilt hät.",
  ["Sabbat", "Matte, Tragbett", "Beschniidig"]),
 ("BG-JHN-1010", U(6, 1, 15), "JHN.6.1", CTX_JESUS, "probable", "Der See von Tiberias, Gerstenbrot und Stadien",
  "Herodes Antipas gründete um 20 n. Chr. am Westufer des Sees Gennesaret die Stadt Tiberias und benannte sie nach Kaiser Tiberius (Josephus, Jüdische Altertümer 18,36–38). Die Bezeichnung «See von Tiberias» ([[JHN.6.1]]; [[JHN.21.1]]) setzt diese Stadt voraus. Der See ist etwa 21 Kilometer lang und an der breitesten Stelle 12 bis 13 Kilometer breit. Gerstenbrot ([[JHN.6.9]]; [[JHN.6.13]]) war billiger als Weizenbrot und galt als Speise der Armen; Elischa speist mit zwanzig Gerstenbroten hundert Männer ([[2KI.4.42-2KI.4.44]]). Zweihundert Denare ([[JHN.6.7]]) entsprachen dem Lohn von etwa zweihundert Arbeitstagen (vgl. [[MAT.20.2]]). Ein Stadion mass rund 185 Meter; 25 oder 30 Stadien ([[JHN.6.19]]) sind etwa 4,6 bis 5,5 Kilometer.",
  "Masse und Löhne sind Näherungswerte; der Wert des Denars schwankte, und nicht jeder Tag brachte Arbeit.",
  ["JHN.6.1-JHN.6.19", "JHN.21.1", "2KI.4.42-2KI.4.44", "MAT.20.2"], ["Josephus, Jüdische Altertümer 18,36–38"],
  [("grc", "κρίθινος", "aus Gerste"), ("grc", "στάδιον", "Stadion, Längenmass von rund 185 Metern"), ("grc", "δηνάριον", "Denar, römische Silbermünze")],
  "De See vo Tiberias, Gerschtebroot und Stadie",
  "De Herodes Antipas hät um 20 n. Chr. am Weschtufer vom See Gennesaret d Stadt Tiberias gründet und si nach em Kaiser Tiberius benännt (Josephus, Jüdischi Altertümer 18,36–38). D Bezeichnig «See vo Tiberias» ([[JHN.6.1]]; [[JHN.21.1]]) setzt die Stadt voruus. De See isch öppe 21 Kilometer lang und a de breitischte Stell 12 bis 13 Kilometer breit. Gerschtebroot ([[JHN.6.9]]; [[JHN.6.13]]) isch billiger gsii als Weizebroot und hät als Ässe vo de Arme gulte; de Elischa macht mit zwänzg Gerschtebroot hundert Manne satt ([[2KI.4.42-2KI.4.44]]). Zweihundert Denar ([[JHN.6.7]]) händ em Lohn vo öppe zweihundert Arbetstäg entsproche (vgl. [[MAT.20.2]]). Es Stadion hät rund 185 Meter gmässe; 25 oder 30 Stadie ([[JHN.6.19]]) sind öppe 4,6 bis 5,5 Kilometer.",
  "Määs und Löhn sind Nööcherigswärt; de Wärt vom Denar hät gschwankt, und nöd jede Tag hät Arbet bracht.",
  ["us Gerschte", "Stadion, Längemäss vo rund 185 Meter", "Denar, römischi Silbermünze"]),
 ("BG-JHN-1011", U(6, 22, 34), "JHN.6.31", CTX_JESUS, "probable", "Die Erwartung neuen Mannas",
  "Das Manna in der Wüste ([[EXO.16.4-EXO.16.15]]) heisst in den Psalmen «Himmelsgetreide» und «Brot der Starken» ([[PSA.78.24-PSA.78.25]]; vgl. [[NEH.9.15]]; [[WIS.16.20]]). In jüdischen Schriften um das Jahr 100 n. Chr. findet sich die Erwartung, in der Heilszeit werde das Manna wieder vom Himmel fallen (syrische Baruch-Apokalypse); ein späterer Midrasch sagt: Wie der erste Erlöser (Mose) Manna herabkommen liess, so wird es auch der letzte Erlöser tun (Kohelet Rabba 1,9). Vor diesem Hintergrund passt die Bitte der Menge um ein Zeichen wie das Manna, nachdem Jesus Brot ausgeteilt hat und sie ihn für «den Propheten» halten ([[JHN.6.14]]; [[JHN.6.30-JHN.6.31]]).",
  "2. Baruch ist etwa gleichzeitig mit dem Johannesevangelium oder etwas jünger, der Midrasch deutlich jünger; wie verbreitet die Erwartung zur Zeit Jesu war, ist nicht sicher.",
  ["JHN.6.14", "JHN.6.30-JHN.6.35", "EXO.16.4-EXO.16.15", "PSA.78.24-PSA.78.25", "NEH.9.15", "WIS.16.20"], ["2. Baruch 29,8", "Kohelet Rabba 1,9"],
  [("grc", "μάννα", "Manna"), ("heb", "מָן", "Manna", "mān")],
  "D Erwartig vo nöiem Manna",
  "S Manna i de Wüeschti ([[EXO.16.4-EXO.16.15]]) heisst i de Psalme «Himmelschorn» und «Broot vo de Starche» ([[PSA.78.24-PSA.78.25]]; vgl. [[NEH.9.15]]; [[WIS.16.20]]). I jüdische Schrifte um s Jaar 100 n. Chr. findt sich d Erwartig, i de Ziit vom Heil fallti s Manna wider vom Himmel (syrischi Baruch-Apokalypse); en spöötere Midrasch seit: Wie de erscht Erlöser (de Mose) Manna hät la abechoo, so wird s au de letscht Erlöser mache (Kohelet Rabba 1,9). Vor däm Hintergrund passt d Bitt vo de Mängi um es Zeiche wie s Manna, nachdem de Jesus Broot uusteilt hät und si en für «de Prophet» halted ([[JHN.6.14]]; [[JHN.6.30-JHN.6.31]]).",
  "S 2. Baruch isch öppe gliichziitig mit em Johannesevangelium oder echli jünger, de Midrasch tüütlich jünger; wie verbreitet d Erwartig zur Ziit vom Jesus gsii isch, isch nöd sicher.",
  ["Manna", "Manna"]),
 ("BG-JHN-1012", U(7, 37, 44), "JHN.7.37", CTX_JESUS, "probable", "Das Laubhüttenfest: Wasser und Licht",
  "Das Laubhüttenfest (Sukkot) war das Fest am Ende der Ernte im Herbst: sieben Tage, an denen man in Hütten wohnte, und ein achter Tag der Festversammlung ([[LEV.23.33-LEV.23.43]]; [[DEU.16.13-DEU.16.15]]; [[NUM.29.35]]). Es war eines der drei Wallfahrtsfeste. Nach der Mischna holte ein Priester an jedem Festmorgen mit einer goldenen Kanne Wasser aus dem Teich Schiloach und goss es am Altar aus (Sukka 4,9); wer die Freude des Wasserschöpfens nicht gesehen habe, habe nie Freude gesehen (5,1). Im Frauenvorhof wurden grosse Leuchter entzündet, die ganz Jerusalem erhellten (5,2–4). Das Fest war mit der Bitte um Regen verbunden; [[ZEC.14.8]] und [[ZEC.14.16-ZEC.14.19]] verbinden lebendiges Wasser aus Jerusalem mit dem Laubhüttenfest der Völker.",
  "Die Mischna beschreibt den Tempelbrauch nach dessen Zerstörung; wie genau sie die Zeit Jesu wiedergibt, ist offen. Ob «der letzte, grosse Tag» ([[JHN.7.37]]) der siebte oder der achte Tag ist, ist umstritten.",
  ["JHN.7.2", "JHN.7.37-JHN.7.39", "LEV.23.33-LEV.23.43", "DEU.16.13-DEU.16.15", "NUM.29.35", "ZEC.14.8", "ZEC.14.16-ZEC.14.19"], ["Mischna, Sukka 4,9; 5,1–4"],
  [("grc", "σκηνοπηγία", "Laubhüttenfest"), ("heb", "סֻכּוֹת", "Laubhütten", "sukkōt")],
  "S Laubhüttefäscht: Wasser und Liecht",
  "S Laubhüttefäscht (Sukkot) isch s Fäscht am Änd vo de Ärn im Herbscht gsii: sibe Täg, wo me i Hütte gwohnt hät, und en achte Tag vo de Fäschtversammlig ([[LEV.23.33-LEV.23.43]]; [[DEU.16.13-DEU.16.15]]; [[NUM.29.35]]). Es isch eis vo de drüü Wallfaartsfäscht gsii. Nach de Mischna hät en Prieschter a jedem Fäschtmorge mit ere guldige Channe Wasser us em Teich Schiloach gholt und s am Altar usgschüttet (Sukka 4,9); wer d Freud vom Wasserschöpfe nöd gseh heb, heb nie Freud gseh (5,1). Im Frauevorhof hät me grossi Lüchter aazündt, wo ganz Jerusalem erhellt händ (5,2–4). S Fäscht isch mit de Bitt um Rääge verbunde gsii; [[ZEC.14.8]] und [[ZEC.14.16-ZEC.14.19]] verbinded läbigs Wasser us Jerusalem mit em Laubhüttefäscht vo de Völker.",
  "D Mischna beschriibt de Bruuch im Tämpel nach dere Zerstörig; wie gnau si d Ziit vom Jesus widergit, isch offe. Öb «de letscht, gross Tag» ([[JHN.7.37]]) de sibet oder de acht Tag isch, isch umstritte.",
  ["Laubhüttefäscht", "Laubhütte"]),
 ("BG-JHN-1013", U(7, 25, 31), "JHN.7.27", CTX_JESUS, "possible", "Woher kommt der Christus?",
  "Zwei Erwartungen stehen in Kapitel 7 nebeneinander. Nach [[MIC.5.2]] und der Überlieferung von David kommt der Gesalbte aus Betlehem und aus Davids Nachkommenschaft ([[JHN.7.42]]; vgl. [[1SA.16.1]]; [[2SA.7.12-2SA.7.16]]). Daneben ist die Vorstellung eines verborgenen Messias bezeugt: Im Dialog mit Tryphon lässt Justin den jüdischen Gesprächspartner sagen, der Christus sei, auch wenn er schon geboren sei, unbekannt, bis Elija komme und ihn salbe (8,4; 110,1); im 4. Esrabuch und im äthiopischen Henochbuch ist der Erwählte bzw. der Sohn bis zu seinem Tag verborgen (siehe die Quellenangaben). Darauf passt der Satz «wenn aber der Christus kommt, weiss niemand, woher er ist» ([[JHN.7.27]]).",
  "Justin schreibt um 160 n. Chr., das 4. Esrabuch entstand gegen Ende des 1. Jahrhunderts; beide sind jünger als die Zeit Jesu. Wie weit diese Vorstellungen zur Zeit Jesu verbreitet waren, ist offen.",
  ["JHN.7.27", "JHN.7.41-JHN.7.42", "MIC.5.2", "1SA.16.1", "2SA.7.12-2SA.7.16"],
  ["Justin, Dialog mit Tryphon 8,4; 110,1", "4. Esra 13,51–52", "1. Henoch 48,6"],
  [("grc", "Χριστός", "Gesalbter, Christus"), ("heb", "מָשִׁיחַ", "Gesalbter, Messias", "māšîaḥ")],
  "Vo wo chunnt de Christus?",
  "Zwei Erwartige stönd im Kapitel 7 näbenand. Nach [[MIC.5.2]] und de Überliferig vom David chunnt de Gsalbet vo Betlehem und us de Nachkommeschaft vom David ([[JHN.7.42]]; vgl. [[1SA.16.1]]; [[2SA.7.12-2SA.7.16]]). Denebe isch d Vorstellig vo me verborgne Messias bezüügt: Im Dialog mit em Tryphon laat de Justin de jüdisch Gsprächspartner säge, de Christus seg, au wänn er scho gebore seg, unbekannt, bis de Elija chömi und en salbi (8,4; 110,1); im 4. Esrabuech und im äthiopische Henochbuech isch de Userwählt bzw. de Sohn bis zu sim Tag verborge (lueg d Quälle-Aagaabe). Dezue passt de Satz «wänn aber de Christus chunnt, weiss niemer, wohär er isch» ([[JHN.7.27]]).",
  "De Justin schriibt um 160 n. Chr., s 4. Esrabuech isch gäge s Änd vom 1. Jaarhundert entstande; beidi sind jünger als d Ziit vom Jesus. Wie wiit die Vorstellige zur Ziit vom Jesus verbreitet gsii sind, isch offe.",
  ["Gsalbete, Christus", "Gsalbete, Messias"]),
 ("BG-JHN-1014", U(1, 35, 42), "JHN.1.38", CTX_READERS, "possible", "Erklärungen für die Leser",
  "Das Evangelium übersetzt mehrfach semitische Wörter: Rabbi heisst «Lehrer» ([[JHN.1.38]]), Messias «Christus» ([[JHN.1.41]]), Kephas «Petrus» ([[JHN.1.42]]), später auch Schiloach, Gabbata, Golgota und Rabbuni ([[JHN.9.7]]; [[JHN.19.13]]; [[JHN.19.17]]; [[JHN.20.16]]). Es erklärt jüdische Bräuche und Verhältnisse: die Krüge «für die Reinigung der Juden» ([[JHN.2.6]]), das Verhältnis von Juden und Samaritern ([[JHN.4.9]]), das Passa als «Fest der Juden» ([[JHN.6.4]]). Zugleich setzt es Kenntnis der Schrift und ihrer Gestalten voraus (Mose, Jakob, Elija, Manna, die erhöhte Schlange). Das passt zu einer griechischsprachigen Leserschaft, in der nicht alle Aramäisch verstanden oder mit jüdischen Bräuchen vertraut waren.",
  "Aus solchen Erklärungen lässt sich die Zusammensetzung der Leserschaft nur vorsichtig erschliessen; sie können auch Stilmittel sein oder auf eine spätere Bearbeitung zurückgehen.",
  ["JHN.1.38", "JHN.1.41-JHN.1.42", "JHN.2.6", "JHN.4.9", "JHN.6.4", "JHN.9.7", "JHN.19.13", "JHN.19.17", "JHN.20.16"], [],
  [("arc", "רַבִּי", "mein Lehrer, mein Meister", "rabbī"), ("arc", "כֵּיפָא", "Fels, Stein", "kēpā")],
  "Erklärige für d Läser",
  "S Evangelium übersetzt meermals semitischi Wörter: Rabbi heisst «Lehrer» ([[JHN.1.38]]), Messias «Christus» ([[JHN.1.41]]), Kephas «Petrus» ([[JHN.1.42]]), spööter au Schiloach, Gabbata, Golgota und Rabbuni ([[JHN.9.7]]; [[JHN.19.13]]; [[JHN.19.17]]; [[JHN.20.16]]). Es erklärt jüdischi Bräuch und Verhältnis: d Chrüeg «für d Reinigung vo de Jude» ([[JHN.2.6]]), s Verhältnis vo Jude und Samaritaner ([[JHN.4.9]]), s Passa als «Fäscht vo de Jude» ([[JHN.6.4]]). Glichziitig setzt es voruus, dass me d Schrift und iri Gstalte kännt (Mose, Jakob, Elija, Manna, d erhöcht Schlange). Das passt zu ere griechischsprachige Läserschaft, wo nöd alli Aramäisch verstande händ oder mit jüdische Bräuch vertrout gsii sind.",
  "Us settige Erklärige cha me d Zämesetzig vo de Läserschaft nu vorsichtig erschlüüsse; si chönd au Stilmittel sii oder uf e spööteri Bearbeitig zruggaa.",
  ["min Lehrer, min Meischter", "Fels, Stei"]),
]

SUMMARIES = [
 ("SUM-CH-JHN-001",
  "Im Anfang war das Wort, und das Wort war bei Gott und war Gott; durch es ist alles geworden, und in ihm war Leben, das Licht der Menschen. Johannes ist gesandt, vom Licht Zeugnis abzulegen. Das Wort wurde Fleisch und wohnte unter uns; Gott hat niemand je gesehen; der Einzige, der an der Brust des Vaters ist, hat Kunde gebracht. Vor Priestern und Leviten aus Jerusalem bekennt Johannes, er sei nicht der Christus, nicht Elija und nicht der Prophet, sondern die Stimme eines Rufenden in der Wüste. Er nennt Jesus das Lamm Gottes und bezeugt, er habe den Geist auf ihn herabkommen sehen. Zwei seiner Jünger folgen Jesus; Andreas führt seinen Bruder Simon zu ihm, und Jesus sagt ihm, er werde Kephas heissen. Jesus ruft Philippus; Natanaël bekennt ihn als Sohn Gottes und König Israels, und Jesus kündigt an, sie würden den Himmel geöffnet und die Engel Gottes auf den Menschensohn hinauf- und herabsteigen sehen.",
  "Im Aafang isch s Wort gsii, und s Wort isch bi Gott gsii und isch Gott gsii; dur es isch alles worde, und in ihm isch Läbe gsii, s Liecht vo de Mänsche. De Johannes isch gschickt, vom Liecht Zügnis z gää. S Wort isch Fleisch worde und hät under üs gwohnt; Gott hät nie öpper gseh; de Einzig, wo a de Bruscht vom Vatter isch, hät Bricht gää. Vor Prieschter und Levite us Jerusalem bekännt de Johannes, er seg nöd de Christus, nöd de Elija und nöd de Prophet, sondern d Stimm vo eim, wo i de Wüeschti rüeft. Er nännt de Jesus s Lamm vo Gott und bezüügt, er heb de Geischt uf ihn abechoo gseh. Zwei vo sine Jünger gönd em Jesus nache; de Andreas bringt sin Brüeder Simon zu ihm, und de Jesus seit em, er wärdi Kephas heisse. De Jesus rüeft de Philippus; de Natanaël bekännt en als Sohn vo Gott und König vo Israel, und de Jesus kündet aa, si wärdid de Himmel offe gseh und d Ängel vo Gott uf de Mänschesohn ufe- und abestiige."),
 ("SUM-CH-JHN-002",
  "Bei einer Hochzeit in Kana geht der Wein aus. Jesu Mutter sagt es ihm; er antwortet, seine Stunde sei noch nicht gekommen, doch sie heisst die Diener tun, was er sagt. Auf sein Wort füllen sie sechs steinerne Krüge mit Wasser und bringen davon dem Speisemeister, der das zu Wein gewordene Wasser kostet und dem Bräutigam sagt, er habe den guten Wein bis jetzt aufbewahrt. Das ist der Anfang der Zeichen: Jesus offenbart seine Herrlichkeit, und seine Jünger glauben an ihn. Vor dem Passa treibt Jesus in Jerusalem die Händler und Geldwechsler aus dem Tempel. Nach einem Zeichen gefragt, sagt er: «Reisst diesen Tempel nieder, und in drei Tagen werde ich ihn aufrichten»; er spricht vom Tempel seines Leibes, woran sich die Jünger nach seiner Auferweckung erinnern. Viele glauben wegen seiner Zeichen an ihn, doch er vertraut sich ihnen nicht an, weil er weiss, was im Menschen ist.",
  "Amene Hochziit z Kana gaat de Wii uus. D Mueter vom Jesus seit s em; er antwortet, sini Stund seg no nöd choo, aber si seit de Diener, si söled mache, was er seit. Uf sis Wort füllet si sächs steinigi Chrüeg mit Wasser und bringed devo em Spiismeischter, wo s Wasser, wo zu Wii worde isch, probiert und em Brüütigam seit, er heb de guet Wii bis jetzt ufbhalte. Das isch de Aafang vo de Zeiche: De Jesus offebaret sini Herrlichkeit, und sini Jünger glaubed a ihn. Vor em Passa tribt de Jesus z Jerusalem d Händler und d Gäldwächsler us em Tämpel. Wo me en nach eme Zeiche fraget, seit er: «Riissed dä Tämpel ab, und i drüü Täg stell ich en uf»; er redt vom Tämpel vo sim Liib, und dra erinnered sich d Jünger nach sinere Uferweckig. Vili glaubed wäg sine Zeiche a ihn, aber er vertrout sich ine nöd aa, wil er weiss, was im Mänsch isch."),
 ("SUM-CH-JHN-003",
  "Der Pharisäer Nikodemus kommt bei Nacht zu Jesus. Jesus sagt ihm, wer nicht von oben, aus Wasser und Geist geboren werde, könne das Reich Gottes nicht sehen und nicht hineinkommen; Nikodemus versteht es nicht. Wie Mose die Schlange in der Wüste erhöht hat, muss der Menschensohn erhöht werden. Denn so hat Gott die Welt geliebt, dass er den einzigen Sohn gab, damit jeder, der an ihn glaubt, nicht verloren geht, sondern ewiges Leben hat; er hat ihn nicht gesandt, die Welt zu richten, sondern damit sie gerettet wird. In Judäa tauft Jesus, während auch Johannes noch tauft. Als die Jünger des Johannes melden, alle gingen zu Jesus, vergleicht sich Johannes mit dem Freund des Bräutigams: «Er muss wachsen, ich aber kleiner werden.» Der von oben kommt, ist über allen; wer an den Sohn glaubt, hat ewiges Leben.",
  "De Pharisäer Nikodemus chunnt znacht zum Jesus. De Jesus seit em, wer nöd vo obe, us Wasser und Geischt gebore wärdi, chönn s Riich vo Gott nöd gseh und nöd inechoo; de Nikodemus verstaat s nöd. Wie de Mose d Schlange i de Wüeschti erhöcht hät, mues de Mänschesohn erhöcht wärde. Dänn so hät Gott d Wält gliebt, dass er de einzig Sohn gää hät, demit jede, wo a ihn glaubt, nöd verlore gaat, sondern ewigs Läbe hät; er hät en nöd gschickt, zum d Wält richte, sondern demit si grettet wird. Z Judäa tauft de Jesus, während au de Johannes no tauft. Wo d Jünger vom Johannes mälded, alli gönged zum Jesus, verglicht sich de Johannes mit em Fründ vom Brüütigam: «Er mues wachse, ich aber chliiner wärde.» Dä, wo vo obe chunnt, isch über allne; wer a de Sohn glaubt, hät ewigs Läbe."),
 ("SUM-CH-JHN-004",
  "Jesus verlässt Judäa und zieht durch Samarien. An der Jakobsquelle bei Sychar bittet er eine samaritische Frau um Wasser und spricht von lebendigem Wasser, das in dem, der davon trinkt, zur Quelle wird, die ins ewige Leben sprudelt. Er sagt ihr, dass sie fünf Männer gehabt hat; sie hält ihn für einen Propheten und fragt nach dem rechten Ort der Anbetung. Jesus antwortet, die Stunde komme und sei jetzt da, in der man den Vater in Geist und Wahrheit anbetet; als sie vom kommenden Messias spricht, sagt er: «Ich bin es, der mit dir redet.» Die Frau ruft die Leute der Stadt; den Jüngern sagt Jesus, seine Speise sei, den Willen dessen zu tun, der ihn gesandt hat, und die Felder seien reif zur Ernte. Viele Samariter glauben und nennen ihn den Retter der Welt. Wieder in Kana, bittet ihn ein königlicher Beamter für seinen todkranken Sohn in Kafarnaum; Jesus sagt: «Geh! Dein Sohn lebt.» Der Mann glaubt dem Wort, und der Sohn wird zu eben dieser Stunde gesund; das ist das zweite Zeichen.",
  "De Jesus verlaat Judäa und gaat dur Samarie. A de Jakobsquälle bi Sychar bittet er e samaritanischi Frau um Wasser und redt vo läbigem Wasser, wo i dem, wo devo trinkt, zu ere Quälle wird, wo is ewig Läbe sprudlet. Er seit ire, dass si föif Manne gha hät; si haltet en für en Prophet und fraget nach em rächte Ort zum Aabätte. De Jesus antwortet, d Stund chömi und seg jetzt da, wo me de Vatter im Geischt und i de Wahrheit aabättet; wo si vom Messias redt, wo chunnt, seit er: «Ich bi s, wo mit dir redt.» D Frau rüeft d Lüüt vo de Stadt; de Jünger seit de Jesus, sini Spiis seg, de Wille vo dem z tue, wo en gschickt hät, und d Fälder seged riif zur Ärn. Vili Samaritaner glaubed und nänned en de Retter vo de Wält. Wider z Kana bittet en en königliche Beamte für sin todchranke Sohn z Kafarnaum; de Jesus seit: «Gang! Din Sohn läbt.» De Maa glaubt em Wort, und de Sohn wird grad i dere Stund gsund; das isch s zweit Zeiche."),
 ("SUM-CH-JHN-005",
  "An einem Fest der Juden heilt Jesus in Jerusalem am Teich Betesda einen Mann, der achtunddreissig Jahre krank war: «Steh auf, nimm deine Matte und geh umher!» Weil es Sabbat ist, halten die Juden dem Geheilten vor, die Matte zu tragen, und verfolgen Jesus. Als er sagt: «Mein Vater wirkt bis jetzt, und auch ich wirke», suchen sie umso mehr, ihn zu töten, weil er Gott seinen eigenen Vater nennt und sich Gott gleich macht. Jesus antwortet, der Sohn könne nichts von sich aus tun, sondern tue, was er den Vater tun sieht; wie der Vater mache auch der Sohn lebendig, und der Vater habe ihm das ganze Gericht übergeben. Wer sein Wort hört und dem glaubt, der ihn gesandt hat, hat ewiges Leben. Für ihn zeugen Johannes, die Werke, die er tut, der Vater und die Schriften; Mose, auf den sie hoffen, klagt sie an, denn er hat über ihn geschrieben.",
  "Amene Fäscht vo de Jude heilt de Jesus z Jerusalem am Teich Betesda en Maa, wo achtedrissg Jaar chrank gsii isch: «Stand uf, nimm dini Matte und lauf umenand!» Wil Sabbat isch, halted d Jude em Gheilte vor, dass er d Matte treit, und verfolged de Jesus. Wo n er seit: «Min Vatter wirkt bis jetzt, und au ich wirke», sueched si no meh, en z töte, wil er Gott sin eigete Vatter nännt und sich Gott gliich macht. De Jesus antwortet, de Sohn chönn nüüt vo sich us mache, sondern mach, was er de Vatter gseet mache; wie de Vatter mach au de Sohn läbig, und de Vatter heb em s ganz Gricht übergää. Wer sis Wort ghört und däm glaubt, wo en gschickt hät, hät ewigs Läbe. Für ihn züüged de Johannes, d Wärch, won er macht, de Vatter und d Schrifte; de Mose, uf dä si hoffed, chlagt si aa, dänn er hät über ihn gschribe."),
 ("SUM-CH-JHN-006",
  "Kurz vor dem Passa folgt Jesus eine grosse Menge an den See von Galiläa. Mit den fünf Gerstenbroten und zwei Fischen eines Jungen macht er etwa fünftausend Männer satt; zwölf Körbe mit Brocken bleiben übrig. Die Leute halten ihn für den Propheten und wollen ihn zum König machen; er zieht sich allein auf den Berg zurück. In der Nacht kommt er auf dem See zu den Jüngern: «Ich bin es; fürchtet euch nicht!» In Kafarnaum hält er der Menge vor, sie suche ihn, weil sie satt geworden sei; als sie ein Zeichen verlangt und an das Manna erinnert, sagt er: «Ich bin das Brot des Lebens.» Wer zu ihm kommt und an ihn glaubt, hat ewiges Leben, und er wird ihn am letzten Tag auferwecken. Als er sagt, wer sein Fleisch isst und sein Blut trinkt, habe ewiges Leben, streiten die Juden, und viele Jünger murren und ziehen sich zurück. Auf seine Frage an die Zwölf antwortet Simon Petrus: «Herr, zu wem sollen wir gehen? Du hast Worte ewigen Lebens.» Jesus sagt, einer von ihnen sei ein Teufel, und meint Judas.",
  "Churz vor em Passa gaat e grossi Mängi em Jesus nache an See vo Galiläa. Mit de föif Gerschtebroot und zwei Fisch vo me Bueb macht er öppe föiftuusig Manne satt; zwölf Chörb mit Brocke bliibed übrig. D Lüüt halted en für de Prophet und wänd en zum König mache; er zieht sich elei uf de Bärg zrugg. I de Nacht chunnt er uf em See zu de Jünger: «Ich bi s; händ kei Angscht!» Z Kafarnaum haltet er de Mängi vor, si sueched en, wil si satt worde seged; wo si es Zeiche verlanged und as Manna erinnered, seit er: «Ich bi s Broot vom Läbe.» Wer zu ihm chunnt und a ihn glaubt, hät ewigs Läbe, und er wird en am letschte Tag uferwecke. Wo n er seit, wer sis Fleisch issi und sis Bluet trinki, heb ewigs Läbe, strited d Jude, und vili Jünger murred und zieed sich zrugg. Uf sini Frag a d Zwölf antwortet de Simon Petrus: «Herr, zu wem söled mer gaa? Du häsch Wort vom ewige Läbe.» De Jesus seit, eine vo ine seg en Tüüfel, und meint de Judas."),
 ("SUM-CH-JHN-007",
  "Weil die Juden ihn töten wollen, zieht Jesus in Galiläa umher. Seine Brüder, die nicht an ihn glauben, drängen ihn, zum Laubhüttenfest nach Judäa zu gehen und sich der Welt zu offenbaren; er sagt, seine Zeit sei noch nicht da, geht dann aber nicht öffentlich, sondern gleichsam im Verborgenen hinauf. Mitten im Fest lehrt er im Tempel: Seine Lehre sei die dessen, der ihn gesandt hat; seine Heilung am Sabbat verteidigt er mit der Beschneidung, die man am Sabbat vollzieht. Die Leute fragen sich, ob er der Christus sei, wenden aber ein, sie wüssten, woher er ist; die Hohepriester und Pharisäer senden Diener, um ihn festzunehmen. Am letzten, grossen Tag des Festes ruft Jesus: «Wenn jemand Durst hat, soll er zu mir kommen und trinken!»; der Erzähler bezieht das auf den Geist. Seinetwegen kommt es zu einer Spaltung in der Menge. Die Diener kehren ohne ihn zurück: Noch nie habe ein Mensch so geredet. Nikodemus fragt, ob das Gesetz einen Menschen richte, ohne ihn zuerst anzuhören, und wird von den Pharisäern zurückgewiesen. Mit «Und jeder ging in sein Haus» ([[JHN.7.53]]) beginnt der Abschnitt von der Ehebrecherin, den der SBLGNT in Doppelklammern setzt.",
  "Wil d Jude en wänd töte, zieht de Jesus z Galiläa umenand. Sini Brüeder, wo nöd a ihn glaubed, dränged en, as Laubhüttefäscht uf Judäa z gaa und sich de Wält z zeige; er seit, sini Ziit seg no nöd da, gaat dänn aber nöd öffentlich, sondern wie im Verborgne ufe. Mitte im Fäscht lehrt er im Tämpel: Sini Leer seg die vo dem, wo en gschickt hät; sini Heilig am Sabbat verteidiget er mit de Beschniidig, wo me am Sabbat macht. D Lüüt fröged sich, öb er de Christus seg, wänded aber ii, si wüssed, wohär er isch; d Hoheprieschter und d Pharisäer schicked Diener, zum en feschtnää. Am letschte, grosse Tag vom Fäscht rüeft de Jesus: «Wänn öpper Durscht hät, söll er zu mir cho und trinke!»; de Erzähler bezieht das uf de Geischt. Wäge ihm git s e Spaltig i de Mängi. D Diener chömed ohni ihn zrugg: No nie heb en Mänsch eso gredt. De Nikodemus fragt, öb s Gsetz en Mänsch richti, ohni en zerscht aazlose, und d Pharisäer wiised en zrugg. Mit «Und jede isch i sis Huus gange» ([[JHN.7.53]]) fangt de Abschnitt vo de Eebrächerin aa, wo de SBLGNT i Doppelchlammere setzt."),
]


